def W(name, obj):
    obj = dict(schema_version=1, reviewed=REVIEWED, updated=REVIEWED, **obj)
    s = unicodedata.normalize("NFC", json.dumps(obj, ensure_ascii=False, indent=1))
    open(os.path.join(D, name), "w", encoding="utf-8").write(s + "\n")
